#!/bin/sh
# 静态库循环依赖：两种顺序都失败，--start-group 反复扫描才收敛
# 期望输出见 expected_output（本机 MinGW 工具链真实执行捕获）

cat > a1.c << 'EOF'
/* liba 成员一：被 libb 依赖的 fa */
int fa(void)
{
    return 1;
}
EOF

cat > a2.c << 'EOF'
/* liba 成员二：自己又依赖 libb 的 g */
extern int g(void);

int fa_uses_g(void)
{
    return g() + 1;
}
EOF

cat > b1.c << 'EOF'
/* libb 成员一：被 liba 依赖的 g */
int g(void)
{
    return 100;
}
EOF

cat > b2.c << 'EOF'
/* libb 成员二：自己又依赖 liba 的 fa */
extern int fa(void);

int g_uses_fa(void)
{
    return fa() * 10;
}
EOF

cat > main.c << 'EOF'
#include <stdio.h>

int fa_uses_g(void);
int g_uses_fa(void);

int main(void)
{
    printf("fa_uses_g() = %d\n", fa_uses_g());
    printf("g_uses_fa() = %d\n", g_uses_fa());
    return 0;
}
EOF

gcc -c a1.c -o a1.o
gcc -c a2.c -o a2.o
ar rcs liba.a a1.o a2.o
gcc -c b1.c -o b1.o
gcc -c b2.c -o b2.o
ar rcs libb.a b1.o b2.o
gcc -c main.c -o main.o
gcc main.o -L. -la -lb -o appA   # 失败：b2.o 需要 fa 时 liba 已扫完
gcc main.o -L. -lb -la -o appB   # 对称失败：a2.o 需要 g 时 libb 已扫完
gcc main.o -L. -Wl,--start-group -la -lb -Wl,--end-group -o appC   # 反复扫描至收敛
./appC
